// The web app talks ONLY to the FastAPI. If the API is slow or down, it falls back to cached JSON
// snapshots in /public/cache (generated by `python scripts/cache_api.py`), and says so on screen.

export const API_URL = (process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000").replace(/\/$/, "");
const TIMEOUT_MS = 15000;

export type Source = "api" | "cache";
export interface Fetched<T> { data: T; source: Source }

type Params = Record<string, string | number | boolean | undefined | null>;

export function qs(params: Params = {}): string {
  const u = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => { if (v !== undefined && v !== null && v !== "") u.set(k, String(v)); });
  const s = u.toString();
  return s ? `?${s}` : "";
}

/** Stable cache file name for an endpoint + params (same rule as scripts/cache_api.py). */
export function cacheKey(path: string, params: Params = {}): string {
  const keys = Object.keys(params).filter((k) => params[k] !== undefined && params[k] !== null && params[k] !== "").sort();
  const tail = keys.map((k) => `${k}-${params[k]}`).join("_");
  return (path.replace(/^\//, "").replace(/[/.]/g, "-") + (tail ? `__${tail}` : "")).replace(/[^a-zA-Z0-9_\-]/g, "");
}

/** GET a JSON resource. `signal` cancels stale requests (TanStack Query passes one per query). */
export async function getJSON<T>(path: string, params: Params = {}, signal?: AbortSignal): Promise<Fetched<T>> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(new DOMException("timeout", "TimeoutError")), TIMEOUT_MS);
  const onAbort = () => ctrl.abort(signal?.reason);
  signal?.addEventListener("abort", onAbort);
  try {
    const r = await fetch(`${API_URL}${path}${qs(params)}`, { signal: ctrl.signal });
    if (!r.ok) throw new Error(`${r.status} ${(await r.text()).slice(0, 300)}`);
    return { data: (await r.json()) as T, source: "api" };
  } catch (err) {
    if (signal?.aborted) throw err; // superseded by a newer request: no cache fallback
    const c = await fetch(`/cache/${cacheKey(path, params)}.json`).catch(() => null);
    if (c && c.ok) return { data: (await c.json()) as T, source: "cache" };
    throw err;
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener("abort", onAbort);
  }
}

export function csvUrl(params: Params): string {
  return `${API_URL}/export.csv${qs(params)}`;
}
